  "Export your opportunities and evidence notes to a backup file, or merge a backup from another device. Data stays in this browser unless you move it yourself.":"Eksporter muligheter og dokumentasjonsnotater til en sikkerhetskopi, eller flett inn en kopi fra en annen enhet. Dataene blir i denne nettleseren med mindre du flytter dem selv.",
