  "Existing records with matching IDs will be skipped. Nothing currently saved will be overwritten.":"Eksisterende oppføringer med samme ID hoppes over. Ingenting som er lagret, blir overskrevet.",
  "Privacy and portability: opportunities and evidence notes are stored only in this browser. Export a backup to move them to another device; the file may contain sensitive business information, so store it securely. Import merges records and skips matching IDs without overwriting existing data. Cloud sync, live discovery, automatic source verification, recurring monitoring, and outcome-based learning are not connected yet.":"Personvern og flyttbarhet: muligheter og dokumentasjonsnotater lagres bare i denne nettleseren. Eksporter en sikkerhetskopi for å flytte dem til en annen enhet; filen kan inneholde sensitiv forretningsinformasjon, så oppbevar den trygt. Import fletter oppføringer og hopper over like ID-er uten å overskrive data. Skysynkronisering, direkte oppdagelse, automatisk kildeverifisering, løpende overvåking og resultatbasert læring er ikke koblet til ennå.",
