  "steps added to this mission.":"steg lagt til i dette oppdraget.",
  "Those steps could not be added. Nothing after this one was attempted.":"Stegene kunne ikke legges til. Ingenting etter dette ble forsøkt.",
  "The connection dropped while adding steps. The ones already added were kept.":"Forbindelsen falt ut under tillegg av steg. De som allerede ble lagt til, er beholdt.",
  "This mission states an outcome but nothing that would move it yet. These steps are a starting structure, not advice: each one is work you do and evidence you record.":"Dette oppdraget beskriver et mål, men ingenting som flytter det ennå. Stegene er en startstruktur, ikke rådgivning: hvert av dem er arbeid du gjør og dokumentasjon du fører.",
  "This looks like a regulated activity. Nothing here tells you what the rules are — the first step is to get them in writing from the authority that sets them.":"Dette ser ut som en regulert virksomhet. Ingenting her forteller deg hva reglene er — første steg er å få dem skriftlig fra myndigheten som fastsetter dem.",
  "Copy any of these into the success criteria field below if you want them recorded.":"Kopier gjerne noen av disse inn i suksesskriteriene nedenfor hvis du vil ha dem registrert.",
  "Opening something takes these seven steps":"Å åpne noe krever disse sju stegene",
  "Hiring well starts with these five steps":"God ansettelse starter med disse fem stegene",
  "Before building, settle these five things":"Avklar disse fem tingene før du bygger",
  "A first plan for this outcome":"En første plan for dette målet",
  "Identify the authority that licenses this kind of business, and record in writing exactly what it requires":"Finn myndigheten som gir løyve til denne typen virksomhet, og skriv ned nøyaktig hva den krever",
  "Describe precisely who you serve, where they are, and how far they will travel":"Beskriv presist hvem du betjener, hvor de er, og hvor langt de vil reise",
  "Visit the places that already serve them and write down their prices and their gaps":"Besøk stedene som allerede betjener dem, og noter prisene og hullene deres",
  "Work out the setup cost, the monthly running cost, and how many customers cover both":"Regn ut etableringskostnad, månedlig driftskostnad og hvor mange kunder som dekker begge",
  "Shortlist locations and confirm the lease terms and permitted use for each":"Lag en kortliste over lokaler og bekreft leievilkår og tillatt bruk for hvert",
  "List the suppliers and the qualified people you must have on the opening day":"List opp leverandørene og de kvalifiserte folkene du må ha på åpningsdagen",
  "Set the opening date, and write down what would make you stop instead":"Sett åpningsdatoen, og skriv ned hva som i stedet ville fått deg til å stoppe",
  "The licensing requirements are confirmed in writing by the responsible authority":"Løyvekravene er bekreftet skriftlig av ansvarlig myndighet",
  "The break-even number of customers is calculated from real observed prices":"Antall kunder for break-even er regnet ut fra faktisk observerte priser",
  "A location is secured on terms you have read in full":"Et lokale er sikret på vilkår du har lest i sin helhet",
  "Write the one sentence a user would say that proves this was worth building":"Skriv den ene setningen en bruker ville sagt som beviser at dette var verdt å bygge",
  "Name the riskiest assumption this depends on, and why it might be wrong":"Nevn den mest risikable antakelsen dette hviler på, og hvorfor den kan være feil",
  "Find the cheapest test that could prove that assumption wrong this week":"Finn den billigste testen som kan motbevise antakelsen denne uken",
  "Define what you will measure, and the number that means stop":"Definer hva du skal måle, og tallet som betyr stopp",
  "Decide who reviews the evidence with you, and when":"Bestem hvem som går gjennom dokumentasjonen med deg, og når",
  "Write down the work that is not getting done today, in hours per week":"Skriv ned arbeidet som ikke blir gjort i dag, i timer per uke",
  "Define what this person must be able to do unsupervised after three months":"Definer hva denne personen må kunne gjøre uten oppfølging etter tre måneder",
  "Agree the budget, the level, and who makes the final decision":"Bli enig om budsjett, nivå og hvem som tar den endelige avgjørelsen",
  "Prepare the one task that shows whether a candidate can actually do the work":"Lag den ene oppgaven som viser om en kandidat faktisk kan gjøre jobben",
  "Set the date you will decide, with or without the perfect candidate":"Sett datoen du skal bestemme deg, med eller uten den perfekte kandidaten",
  "Write what success looks like in one sentence you could measure":"Skriv hva suksess er i én setning du kan måle",
  "List what must be true for this to work, and mark which you have not checked":"List opp hva som må stemme for at dette skal fungere, og merk hva du ikke har sjekket",
  "Pick the cheapest way to check the one that would hurt most if it were false":"Velg den billigste måten å sjekke den som ville gjort mest skade om den var feil",
  "Set the date you will look at the evidence and decide":"Sett datoen du skal se på dokumentasjonen og bestemme deg",
  "Every assumption is either checked against evidence or openly marked unknown":"Hver antakelse er enten sjekket mot dokumentasjon eller åpent merket som ukjent",
