  "Nothing planned":"Ingenting planlagt",
  "Missions with no work behind them":"Oppdrag uten arbeid bak seg",
  "This mission states an outcome but holds no step that would reach it.":"Dette oppdraget beskriver et mål, men har ingen steg som når det.",
  "Plan it":"Planlegg det",
  "Every mission has at least one step behind it.":"Hvert oppdrag har minst ett steg bak seg.",
  "A follow-up on this mission is already overdue.":"En oppfølging på dette oppdraget er allerede forfalt.",
  "A follow-up on this mission falls due within the week.":"En oppfølging på dette oppdraget forfaller denne uken.",
  "It states an outcome but holds no step that would reach it.":"Det beskriver et mål, men har ingen steg som når det.",
  "Every step on this mission is still unstarted.":"Alle steg i dette oppdraget er ennå ikke påbegynt.",
  "Nothing has moved on this mission for two weeks or more.":"Ingenting har skjedd med dette oppdraget på to uker eller mer.",
  "other mission also needs you.":"annet oppdrag trenger deg også.",
  "other missions also need you.":"andre oppdrag trenger deg også.",
  "A trip holds together on these six":"En reise henger sammen på disse seks",
  "Moving countries turns on these five":"Å flytte land avhenger av disse fem",
  "Committing years to study starts with these five":"Å bruke år på studier starter med disse fem",
  "Write the dates, and what has to be true before you can leave on them":"Skriv datoene, og hva som må stemme før du kan reise på dem",
  "Check what each destination requires from someone with your passport, and how long it takes to get":"Sjekk hva hvert reisemål krever av noen med ditt pass, og hvor lang tid det tar å skaffe",
  "Price the whole trip — travel, stay, moving around, eating, and a margin for the unplanned":"Prissett hele reisen — transport, opphold, lokal reising, mat og en margin for det uforutsette",
  "Book the one thing that is hardest to change, and build the rest around it":"Book det som er vanskeligst å endre, og bygg resten rundt det",
  "List what must be arranged at home while you are away":"List opp hva som må ordnes hjemme mens du er borte",
  "Write down what you would do if a leg of it falls through":"Skriv ned hva du gjør hvis en etappe faller bort",
  "Entry requirements are confirmed from the official source for your passport":"Innreisekravene er bekreftet fra offisiell kilde for ditt pass",
  "The full cost is written down, including a margin for the unplanned":"Hele kostnaden er skrevet ned, inkludert margin for det uforutsette",
  "Confirm what residence permits your situation needs, and the processing time for each":"Bekreft hvilke oppholdstillatelser din situasjon krever, og behandlingstiden for hver",
  "Work out what the first twelve months cost before any income arrives":"Regn ut hva de første tolv månedene koster før noen inntekt kommer",
  "Check what your qualifications are worth there, and what recognition takes":"Sjekk hva kvalifikasjonene dine er verdt der, og hva godkjenning krever",
  "Decide what happens to what you hold now — home, contracts, commitments":"Bestem hva som skjer med det du har nå — bolig, kontrakter, forpliktelser",
  "Set the date you decide, and what evidence would make you stay":"Sett datoen du bestemmer deg, og hva som ville fått deg til å bli",
  "Write what you will be able to do at the end that you cannot do now":"Skriv hva du vil kunne gjøre til slutt som du ikke kan nå",
  "Compare the real entry requirements, cost and length of the options":"Sammenlign de faktiske opptakskravene, kostnaden og lengden på alternativene",
  "Check what the qualification is accepted for where you intend to use it":"Sjekk hva kvalifikasjonen godtas for der du vil bruke den",
  "Plan the hours per week against what your life already holds":"Planlegg timene per uke opp mot det livet ditt allerede rommer",
  "Set the checkpoint where you confirm it is still worth continuing":"Sett sjekkpunktet der du bekrefter at det fortsatt er verdt å fortsette",
  "This mission has no success criteria, so nothing can ever mark it finished.":"Dette oppdraget har ingen suksesskriterier, så ingenting kan noen gang merke det som ferdig.",
  "No step has been recorded, so nothing can move.":"Ingen steg er registrert, så ingenting kan flytte seg.",
  "No step carries a follow-up date, so nothing here will ever ask for you.":"Ingen steg har oppfølgingsdato, så ingenting her vil noen gang be om deg.",
  "“{text}” names a subject, not a result someone could check. Add what must be true, a number, or a date.":"«{text}» navngir et emne, ikke et resultat noen kan sjekke. Legg til hva som må stemme, et tall eller en dato.",
  "“{text}” is also a success criterion. A criterion is how you judge the result; a step is work you do.":"«{text}» er også et suksesskriterium. Et kriterium er hvordan du vurderer resultatet; et steg er arbeid du gjør.",
  "“{text}” uses only words already in the goal, so it restates the outcome instead of naming work.":"«{text}» bruker bare ord som allerede står i målet, og gjentar dermed resultatet i stedet for å navngi arbeid.",
  "Privacy":"Personvern",
  "Terms":"Vilkår",
  "Privacy notice":"Personvernerklæring",
  "Terms of service":"Vilkår for bruk",
  "Mission control for goals you have to get right":"Kontrollsenter for mål du må treffe",
  "Write the outcome you want. Get a first plan back, with the weak parts of your own wording pointed out — then keep the evidence that you reached it.":"Skriv målet du vil nå. Få en første plan tilbake, med de svake punktene i din egen formulering påpekt — og behold dokumentasjonen på at du kom i mål.",
  "Suggestions come from rules in our source code, not from a model guessing. Nothing you write is sent to an AI provider.":"Forslagene kommer fra regler i kildekoden vår, ikke fra en modell som gjetter. Ingenting du skriver sendes til en KI-leverandør.",
  "Filled in from this mission's own success criteria. Change it if what you checked was different.":"Fylt ut fra oppdragets egne suksesskriterier. Endre det hvis du sjekket noe annet.",
  "This mission records no success criteria, so there is nothing to fill in. Write what you actually checked.":"Dette oppdraget har ingen suksesskriterier, så det er ingenting å fylle ut. Skriv hva du faktisk sjekket.",
  "Completed steps you can cite:":"Fullførte steg du kan vise til:",
  "Add this step to the evidence":"Legg dette steget til i dokumentasjonen",
