  "Export your opportunities and evidence notes to a backup file, or merge a backup from another device. Data stays in this browser unless you move it yourself.":"صدّر فرصك وملاحظات أدلتك إلى ملف نسخة احتياطية، أو ادمج نسخة من جهاز آخر. تبقى البيانات في هذا المتصفح ما لم تنقلها بنفسك.",
