  "Privacy and portability: opportunities and evidence notes are stored only in this browser. Export a backup to move them to another device; the file may contain sensitive business information, so store it securely. Import merges records and skips matching IDs without overwriting existing data. Cloud sync, live discovery, automatic source verification, recurring monitoring, and outcome-based learning are not connected yet.":"الخصوصية وقابلية النقل: تُحفظ الفرص وملاحظات الأدلة في هذا المتصفح فقط. صدّر نسخة احتياطية لنقلها إلى جهاز آخر؛ وقد يحتوي الملف على معلومات تجارية حسّاسة، فاحفظه بأمان. الاستيراد يدمج السجلات ويتخطّى المعرّفات المطابقة دون استبدال البيانات الموجودة. أما المزامنة السحابية والاكتشاف الحي والتحقق التلقائي من المصادر والمراقبة الدورية والتعلّم المبني على النتائج فغير موصولة بعد.",
