  "This mission states an outcome but nothing that would move it yet. These steps are a starting structure, not advice: each one is work you do and evidence you record.":"هذه المهمة تذكر نتيجة مرجوّة لكن لا شيء يحرّكها بعد. هذه الخطوات هيكل بداية لا نصيحة: كل خطوة عمل تؤديه ودليل تسجّله.",
  "This looks like a regulated activity. Nothing here tells you what the rules are — the first step is to get them in writing from the authority that sets them.":"يبدو هذا نشاطاً خاضعاً للتنظيم. لا شيء هنا يخبرك بما هي القواعد — الخطوة الأولى أن تحصل عليها مكتوبة من الجهة التي تضعها.",
  "Copy any of these into the success criteria field below if you want them recorded.":"انسخ أياً منها إلى حقل معايير النجاح أدناه إن أردت تسجيلها.",
  "Opening something takes these seven steps":"افتتاح أي نشاط يمرّ بهذه الخطوات السبع",
  "Hiring well starts with these five steps":"التوظيف الجيد يبدأ بهذه الخطوات الخمس",
  "Before building, settle these five things":"قبل أن تبني، احسم هذه الأمور الخمسة",
  "A first plan for this outcome":"خطة أولى لهذه النتيجة",
  "Identify the authority that licenses this kind of business, and record in writing exactly what it requires":"حدّد الجهة التي ترخّص هذا النوع من النشاط، وسجّل كتابةً ما تشترطه بالضبط",
  "Describe precisely who you serve, where they are, and how far they will travel":"صِف بدقة من تخدمهم وأين هم وكم يبعدون استعداداً للوصول إليك",
  "Visit the places that already serve them and write down their prices and their gaps":"زُر الأماكن التي تخدمهم بالفعل وسجّل أسعارها وثغراتها",
  "Work out the setup cost, the monthly running cost, and how many customers cover both":"احسب تكلفة التأسيس والتكلفة الشهرية وعدد العملاء الذي يغطيهما",
  "Shortlist locations and confirm the lease terms and permitted use for each":"اختصر المواقع المحتملة وتحقق من شروط الإيجار والاستخدام المسموح لكل منها",
  "List the suppliers and the qualified people you must have on the opening day":"اكتب قائمة المورّدين والأشخاص المؤهّلين الذين يلزم وجودهم يوم الافتتاح",
  "Set the opening date, and write down what would make you stop instead":"حدّد تاريخ الافتتاح، واكتب ما الذي يجعلك تتوقف بدلاً من ذلك",
  "The licensing requirements are confirmed in writing by the responsible authority":"اشتراطات الترخيص مؤكَّدة كتابةً من الجهة المسؤولة",
  "The break-even number of customers is calculated from real observed prices":"عدد العملاء اللازم لتغطية التكاليف محسوب من أسعار حقيقية رُصدت فعلاً",
  "A location is secured on terms you have read in full":"المكان مؤمَّن بشروط قرأتها كاملة",
  "Write the one sentence a user would say that proves this was worth building":"اكتب الجملة الواحدة التي يقولها المستخدم فتثبت أن بناء هذا كان يستحق",
  "Name the riskiest assumption this depends on, and why it might be wrong":"سمِّ أخطر افتراض يعتمد عليه هذا، ولماذا قد يكون خاطئاً",
  "Find the cheapest test that could prove that assumption wrong this week":"اعثر على أرخص اختبار قد يُثبت خطأ ذلك الافتراض هذا الأسبوع",
  "Define what you will measure, and the number that means stop":"حدّد ما ستقيسه، والرقم الذي يعني التوقف",
  "Decide who reviews the evidence with you, and when":"قرّر من يراجع الأدلة معك ومتى",
  "Write down the work that is not getting done today, in hours per week":"اكتب العمل الذي لا يُنجَز اليوم، بالساعات أسبوعياً",
  "Define what this person must be able to do unsupervised after three months":"حدّد ما يجب أن يقدر هذا الشخص على فعله دون إشراف بعد ثلاثة أشهر",
  "Agree the budget, the level, and who makes the final decision":"اتفق على الميزانية والمستوى ومن يتخذ القرار النهائي",
  "Prepare the one task that shows whether a candidate can actually do the work":"جهّز المهمة الواحدة التي تكشف إن كان المرشّح يقدر فعلاً على العمل",
