  "List what must be true for this to work, and mark which you have not checked":"اكتب ما يجب أن يكون صحيحاً لينجح هذا، وأشِر إلى ما لم تتحقق منه",
  "Pick the cheapest way to check the one that would hurt most if it were false":"اختر أرخص طريقة للتحقق من الافتراض الذي سيضرّ أكثر لو كان خاطئاً",
