  "Check what each destination requires from someone with your passport, and how long it takes to get":"تحقق مما تشترطه كل وجهة على حامل جواز سفرك، وكم يستغرق الحصول عليه",
  "Price the whole trip — travel, stay, moving around, eating, and a margin for the unplanned":"سعّر الرحلة كاملة — التنقل والإقامة والحركة والطعام وهامش لغير المتوقع",
