  "Add the source title and a concise note describing what the source actually says.":"أضف عنوان المصدر وملاحظة موجزة تصف ما يقوله المصدر فعلاً.",
  "This source URL is already attached. Revisit the existing entry instead of counting it twice.":"هذا الرابط مُرفق بالفعل. راجع المدخل الموجود بدل احتسابه مرتين.",
  "Evidence note added. It records your review; Zavqera has not independently verified the source.":"أُضيفت ملاحظة الدليل. هي تسجّل مراجعتك؛ ولم تتحقق Zavqera من المصدر بشكل مستقل.",
  "Browser storage is unavailable. Export or copy important details before leaving this page.":"تخزين المتصفح غير متاح. صدّر أو انسخ التفاصيل المهمة قبل مغادرة الصفحة.",
  "Backup exported: {count} opportunities and {notes} evidence notes. Store the file securely; it contains the details you recorded.":"تم تصدير النسخة الاحتياطية: {count} فرصة و{notes} ملاحظة دليل. احفظ الملف بأمان؛ فهو يحتوي التفاصيل التي سجّلتها.",
  "The backup could not be exported.":"تعذّر تصدير النسخة الاحتياطية.",
  "This file is larger than 2 MB. Nothing was imported.":"هذا الملف أكبر من 2 ميغابايت. لم يُستورد شيء.",
  "The backup could not be read.":"تعذّرت قراءة النسخة الاحتياطية.",
  "Imported {count} opportunities with {notes} evidence notes. {skipped} existing record(s) with matching IDs were skipped; no existing records were overwritten.":"تم استيراد {count} فرصة مع {notes} ملاحظة دليل. وتُخطّي {skipped} سجلاً موجوداً بمعرّفات مطابقة؛ ولم يُستبدل أي سجل قائم.",
  "Nothing was imported because every opportunity ID already exists. Your current records were left unchanged.":"لم يُستورد شيء لأن جميع معرّفات الفرص موجودة بالفعل. وسجلاتك الحالية لم تتغير.",
  "Add an opportunity name and a concise explanation of why it may matter.":"أضف اسماً للفرصة وشرحاً موجزاً لسبب أهميتها المحتملة.",
  "Use a full public http:// or https:// source URL, or leave the field blank.":"استخدم رابط مصدر عام كاملاً يبدأ بـ http:// أو https://، أو اترك الحقل فارغاً.",
  "Add an opportunity before exporting a backup":"أضف فرصة قبل تصدير نسخة احتياطية",
  "Download your opportunity data":"نزّل بيانات فرصك",
  "High score. Verify the source and test the key assumptions before deciding whether to pursue.":"درجة عالية. تحقّق من المصدر واختبر الافتراضات الأساسية قبل أن تقرر المتابعة.",
  "Potentially worthwhile. Test the weakest assumption before investing heavily.":"قد تستحق العناء. اختبر أضعف افتراض قبل استثمار كبير.",
  "Keep on the radar. Improve the evidence or reduce the effort before committing.":"أبقِها قيد المتابعة. حسّن الأدلة أو قلّل الجهد قبل الالتزام.",
