  "Monthly AI usage reservation is invalid. No AI provider was called.":"حجز الاستخدام الشهري للذكاء الاصطناعي غير صالح. لم يُستدعَ أي مزوّد.",
  "The monthly usage reservation could not be confirmed. No AI provider was called.":"تعذّر تأكيد حجز الاستخدام الشهري. لم يُستدعَ أي مزوّد.",
  "The AI provider could not complete this brief. This attempt used one monthly generation; no automatic retry was attempted.":"لم يتمكن مزوّد الذكاء الاصطناعي من إكمال هذا الموجز. استهلكت هذه المحاولة توليدة شهرية واحدة؛ ولم تُجرَ إعادة محاولة تلقائية.",
  "The AI provider returned an unreadable response. This attempt used one monthly generation.":"أعاد مزوّد الذكاء الاصطناعي استجابة غير مقروءة. استهلكت هذه المحاولة توليدة شهرية واحدة.",
  "The AI provider returned an unsupported response. This attempt used one monthly generation.":"أعاد مزوّد الذكاء الاصطناعي استجابة غير مدعومة. استهلكت هذه المحاولة توليدة شهرية واحدة.",
  "The AI provider did not return a complete report. This attempt used one monthly generation.":"لم يُعد مزوّد الذكاء الاصطناعي تقريراً كاملاً. استهلكت هذه المحاولة توليدة شهرية واحدة.",
  "The AI provider returned a report that was not valid JSON. This attempt used one monthly generation.":"أعاد مزوّد الذكاء الاصطناعي تقريراً ليس JSON صالحاً. استهلكت هذه المحاولة توليدة شهرية واحدة.",
  "The report did not pass evidence-reference and structure checks. This attempt used one monthly generation.":"لم يجتز التقرير فحوص مراجع الأدلة والبنية. استهلكت هذه المحاولة توليدة شهرية واحدة.",
