  "The AI report could not be completed. This attempt used one monthly generation; no automatic retry was attempted.":"تعذّر إكمال تقرير الذكاء الاصطناعي. استهلكت هذه المحاولة توليدة شهرية واحدة؛ ولم تُجرَ إعادة محاولة تلقائية.",
