  "Outcome could not be committed. Check your connection and try again.":"تعذّر اعتماد النتيجة. تحقق من اتصالك وحاول مجدداً.",
  "Prepare and validate a small project launch while keeping cost, timing, and risk visible.":"جهّز وتحقّق من إطلاق مشروع صغير مع إبقاء التكلفة والتوقيت والمخاطر ظاهرة.",
  "Compare realistic options using trustworthy evidence and make a decision with assumptions and uncertainties clearly stated.":"قارن خيارات واقعية بأدلة موثوقة، واتخذ قراراً مع ذكر الافتراضات وأوجه عدم اليقين بوضوح.",
  "Improve one recurring workflow without disrupting critical operations, and confirm whether the change helped.":"حسّن سير عمل متكرراً واحداً دون تعطيل العمليات الحرجة، وتأكّد مما إذا كان التغيير قد أفاد.",
  "I asked to be emailed once this plan is available. My address is used for that one message and nothing else.":"طلبتُ أن تصلني رسالة بريدية حين تتوفر هذه الخطة. يُستخدم عنواني لتلك الرسالة وحدها لا غير.",
  "AI analysis is not enabled on this deployment yet. No AI request was sent.":"تحليل الذكاء الاصطناعي غير مفعّل في هذا النشر بعد. لم يُرسَل أي طلب.",
  "AI draft":"مسودة بالذكاء الاصطناعي",
  "Let AI draft the shape of this work":"دع الذكاء الاصطناعي يرسم شكل هذا العمل",
  "It will suggest the steps and what each one is for. It will not tell you a fee, a waiting time or a rule: it has looked nothing up, so anything external comes back as where to confirm it.":"سيقترح الخطوات والغرض من كل واحدة. ولن يخبرك برسم أو مدة انتظار أو قاعدة: فهو لم يبحث في شيء، لذا يعود كل أمر خارجي في صورة «أين تتأكد منه».",
  "Draft a plan":"اصنع مسودة خطة",
  "Drafting…":"جارٍ الصياغة…",
  "Confirm with:":"تأكّد من:",
  "Answer these yourself":"أجب عن هذه بنفسك",
  "Drafted by a model from your own words. Nothing was looked up, and nothing is saved until you add it.":"صاغها نموذج من كلماتك أنت. لم يُبحث في شيء، ولا يُحفظ شيء حتى تضيفه.",
  "Discard this draft":"تجاهل هذه المسودة",
  "The AI plan could not be completed. This attempt used one monthly generation; no automatic retry was attempted.":"تعذّر إكمال خطة الذكاء الاصطناعي. استهلكت هذه المحاولة توليدة شهرية واحدة؛ ولم تُجرَ إعادة محاولة تلقائية.",
  "Sign in to draft a plan with AI.":"سجّل الدخول لصياغة خطة بالذكاء الاصطناعي.",
  "AI planning is limited to approved preview testers.":"التخطيط بالذكاء الاصطناعي مقصور على مختبري المعاينة المعتمدين.",
  "Send the mission as JSON.":"أرسل المهمة بصيغة JSON.",
  "The mission is too long. Shorten the intent and try again.":"المهمة طويلة جداً. اختصر الهدف وحاول مجدداً.",
  "The mission input is invalid.":"مدخلات المهمة غير صالحة.",
  "Too many plans were requested. Wait a few minutes before trying again.":"طُلب عدد كبير من الخطط. انتظر بضع دقائق قبل المحاولة مجدداً.",
  "You've reached the monthly AI allowance for this plan.":"لقد بلغت الحد الشهري للذكاء الاصطناعي في هذه الخطة.",
  "The AI provider could not draft this plan. This attempt used one monthly generation; no automatic retry was attempted.":"لم يتمكن مزوّد الذكاء الاصطناعي من صياغة هذه الخطة. استهلكت هذه المحاولة توليدة شهرية واحدة؛ ولم تُجرَ إعادة محاولة تلقائية.",
  "The AI provider did not return a complete plan. This attempt used one monthly generation.":"لم يُعد مزوّد الذكاء الاصطناعي خطة كاملة. استهلكت هذه المحاولة توليدة شهرية واحدة.",
  "The AI provider returned a plan that was not valid JSON. This attempt used one monthly generation.":"أعاد مزوّد الذكاء الاصطناعي خطة ليست JSON صالحاً. استهلكت هذه المحاولة توليدة شهرية واحدة.",
  "The draft plan stated figures or links it cannot verify, so it was discarded. This attempt used one monthly generation.":"ذكرت المسودة أرقاماً أو روابط لا تستطيع التحقق منها، فأُلغيت. استهلكت هذه المحاولة توليدة شهرية واحدة.",
  "The AI plan timed out. This attempt used one monthly generation; no automatic retry was attempted.":"انتهت مهلة خطة الذكاء الاصطناعي. استهلكت هذه المحاولة توليدة شهرية واحدة؛ ولم تُجرَ إعادة محاولة تلقائية.",
  "The AI provider rejected this deployment's credentials. The API key may have expired, been revoked or been entered incorrectly. This attempt used one monthly generation.":"رفض مزوّد الذكاء الاصطناعي بيانات اعتماد هذا النشر. قد يكون المفتاح منتهي الصلاحية أو مُلغى أو مُدخلاً بشكل خاطئ. استهلكت هذه المحاولة توليدة شهرية واحدة.",
