  "Opportunity Intelligence belongs inside the monthly plan—not as a surprise add-on.":"La inteligencia de oportunidades forma parte del plan mensual, no es un extra sorpresa.",
  "The current early-access feature scores the information you enter, keeps your evidence ledger in this browser, and can turn a reviewed opportunity into a Mission. A guarded server-side AI analyst route exists for restricted preview access only. It is not generally available, and the route does not fetch source pages itself.":"La función actual de acceso anticipado puntúa la información que introduces, guarda tu registro de evidencia en este navegador y puede convertir una oportunidad revisada en una Misión. Existe una ruta de analista con IA en el servidor, protegida y solo para acceso restringido de vista previa. No está disponible de forma general y la ruta no descarga páginas de origen por sí misma.",
  "AI challenge: find weak assumptions, contradictions, missing evidence, and reasons an idea may fail.":"Desafío con IA: detecta supuestos débiles, contradicciones, evidencia ausente y motivos por los que una idea puede fallar.",
  "Evidence-first report: each factual claim must cite a source or be clearly labeled as an inference or unknown.":"Informe basado en evidencia: cada afirmación factual debe citar una fuente o marcarse claramente como inferencia o desconocido.",
  "Market gap: compare relevant competitors, the prices they publish, customer pain signals, and unmet needs when reliable source data is available.":"Brecha de mercado: compara competidores relevantes, los precios que publican, señales de dolor del cliente y necesidades no cubiertas cuando haya datos de origen fiables.",
  "Next best test: recommend a low-cost experiment with success/failure criteria, then create a governed Mission for the user to review.":"Mejor prueba siguiente: recomienda un experimento de bajo coste con criterios de éxito y fracaso, y crea una Misión gobernada para que el usuario la revise.",
  "These are planned capabilities, not currently available features. The monthly report allowances and prices are hypotheses until provider costs, source access, report quality, and demand are tested.":"Son capacidades previstas, no funciones disponibles hoy. Las cuotas mensuales de informes y los precios son hipótesis hasta probar costes del proveedor, acceso a fuentes, calidad del informe y demanda.",
  "Try the current Opportunity Intelligence MVP":"Prueba el MVP actual de Inteligencia de oportunidades",
  "No unsupported promises.":"Sin promesas infundadas.",
  "The first version must be useful without AI; the paid analyst should launch only after source-backed reports, safe limits, privacy controls, and cost per report have been verified.":"La primera versión debe ser útil sin IA; el analista de pago solo debería lanzarse tras verificar informes respaldados por fuentes, límites seguros, controles de privacidad y coste por informe.",
  "Back to ZAVQERA":"Volver a ZAVQERA",
  "Choose a starting point, review every field, and keep control of the mission before you create it.":"Elige un punto de partida, revisa cada campo y mantén el control de la misión antes de crearla.",
  "A template only pre-fills a draft. Nothing is created until you review it and submit the mission form.":"Una plantilla solo rellena un borrador. No se crea nada hasta que lo revises y envíes el formulario.",
