  "Your radar starts here":"Tu radar empieza aquí",
  "Add your first opportunity to begin comparing options. The score is a guide to support your decision, not a market forecast.":"Añade tu primera oportunidad para empezar a comparar opciones. La puntuación es una guía de apoyo a tu decisión, no un pronóstico de mercado.",
