  "Loading opportunities saved in this browser…":"Cargando oportunidades guardadas en este navegador…",
  "Keep your opportunity data portable":"Mantén portables los datos de tus oportunidades",
  "Export your opportunities and evidence notes to a backup file, or merge a backup from another device. Data stays in this browser unless you move it yourself.":"Exporta tus oportunidades y notas de evidencia a un archivo de copia de seguridad, o fusiona una copia de otro dispositivo. Los datos permanecen en este navegador salvo que los muevas tú.",
  "Checking backup file…":"Comprobando el archivo de copia de seguridad…",
  "Import and merge":"Importar y fusionar",
  "Existing records with matching IDs will be skipped. Nothing currently saved will be overwritten.":"Se omitirán los registros existentes con ID coincidentes. No se sobrescribirá nada de lo ya guardado.",
  "Privacy and portability: opportunities and evidence notes are stored only in this browser. Export a backup to move them to another device; the file may contain sensitive business information, so store it securely. Import merges records and skips matching IDs without overwriting existing data. Cloud sync, live discovery, automatic source verification, recurring monitoring, and outcome-based learning are not connected yet.":"Privacidad y portabilidad: las oportunidades y las notas de evidencia se guardan solo en este navegador. Exporta una copia de seguridad para llevarlas a otro dispositivo; el archivo puede contener información empresarial sensible, así que guárdalo de forma segura. La importación fusiona registros y omite los ID coincidentes sin sobrescribir datos existentes. La sincronización en la nube, el descubrimiento en vivo, la verificación automática de fuentes, la monitorización recurrente y el aprendizaje basado en resultados aún no están conectados.",
