  "This mission states an outcome but nothing that would move it yet. These steps are a starting structure, not advice: each one is work you do and evidence you record.":"Esta misión plantea un resultado pero aún nada que lo mueva. Estos pasos son una estructura inicial, no un consejo: cada uno es trabajo que haces y evidencia que registras.",
  "This looks like a regulated activity. Nothing here tells you what the rules are — the first step is to get them in writing from the authority that sets them.":"Esto parece una actividad regulada. Nada aquí te dice cuáles son las reglas: el primer paso es obtenerlas por escrito de la autoridad que las fija.",
  "Copy any of these into the success criteria field below if you want them recorded.":"Copia cualquiera de estos en el campo de criterios de éxito si quieres registrarlos.",
  "Opening something takes these seven steps":"Abrir algo requiere estos siete pasos",
  "Hiring well starts with these five steps":"Contratar bien empieza con estos cinco pasos",
  "Before building, settle these five things":"Antes de construir, resuelve estas cinco cosas",
  "A first plan for this outcome":"Un primer plan para este resultado",
  "Identify the authority that licenses this kind of business, and record in writing exactly what it requires":"Identifica la autoridad que licencia este tipo de negocio y anota por escrito exactamente qué exige",
  "Describe precisely who you serve, where they are, and how far they will travel":"Describe con precisión a quién sirves, dónde está y cuánto se desplazará",
  "Visit the places that already serve them and write down their prices and their gaps":"Visita los lugares que ya los atienden y anota sus precios y sus carencias",
  "Work out the setup cost, the monthly running cost, and how many customers cover both":"Calcula el coste inicial, el coste mensual y cuántos clientes cubren ambos",
  "Shortlist locations and confirm the lease terms and permitted use for each":"Haz una lista corta de locales y confirma las condiciones de alquiler y el uso permitido de cada uno",
  "List the suppliers and the qualified people you must have on the opening day":"Enumera los proveedores y el personal cualificado que necesitas el día de apertura",
  "Set the opening date, and write down what would make you stop instead":"Fija la fecha de apertura y anota qué te haría detenerte en su lugar",
  "The licensing requirements are confirmed in writing by the responsible authority":"Los requisitos de licencia están confirmados por escrito por la autoridad responsable",
  "The break-even number of customers is calculated from real observed prices":"El número de clientes de equilibrio se calcula con precios reales observados",
  "A location is secured on terms you have read in full":"Hay un local asegurado con condiciones que has leído por completo",
  "Write the one sentence a user would say that proves this was worth building":"Escribe la frase que diría un usuario y que demuestra que valía la pena construirlo",
  "Name the riskiest assumption this depends on, and why it might be wrong":"Nombra el supuesto más arriesgado del que depende y por qué podría ser falso",
  "Find the cheapest test that could prove that assumption wrong this week":"Encuentra la prueba más barata que podría refutar ese supuesto esta semana",
  "Define what you will measure, and the number that means stop":"Define qué medirás y el número que significa parar",
  "Decide who reviews the evidence with you, and when":"Decide quién revisa la evidencia contigo y cuándo",
  "Write down the work that is not getting done today, in hours per week":"Anota el trabajo que hoy no se hace, en horas por semana",
  "Define what this person must be able to do unsupervised after three months":"Define qué debe poder hacer esta persona sin supervisión a los tres meses",
  "Agree the budget, the level, and who makes the final decision":"Acuerda el presupuesto, el nivel y quién toma la decisión final",
  "Prepare the one task that shows whether a candidate can actually do the work":"Prepara la única tarea que muestra si un candidato sabe hacer el trabajo",
  "Set the date you will decide, with or without the perfect candidate":"Fija la fecha en que decidirás, con o sin el candidato perfecto",
  "Write what success looks like in one sentence you could measure":"Escribe cómo es el éxito en una frase que puedas medir",
  "List what must be true for this to work, and mark which you have not checked":"Enumera qué debe ser cierto para que funcione y marca lo que no has comprobado",
  "Pick the cheapest way to check the one that would hurt most if it were false":"Elige la forma más barata de comprobar el que más dolería si fuera falso",
  "Set the date you will look at the evidence and decide":"Fija la fecha en que mirarás la evidencia y decidirás",
