  "Committing years to study starts with these five":"Dedicar años al estudio empieza con estos cinco",
  "Write the dates, and what has to be true before you can leave on them":"Escribe las fechas y qué debe cumplirse para poder salir en ellas",
  "Check what each destination requires from someone with your passport, and how long it takes to get":"Comprueba qué exige cada destino a alguien con tu pasaporte y cuánto tarda en obtenerse",
  "Price the whole trip — travel, stay, moving around, eating, and a margin for the unplanned":"Presupuesta todo el viaje: transporte, alojamiento, desplazamientos, comida y un margen para lo imprevisto",
