  "Create your first mission to start tracking a concrete outcome.":"Créez votre première mission pour suivre un résultat concret.",
  "Create first mission":"Créer la première mission",
  "Missions and follow-ups that need your attention.":"Missions et suivis qui demandent votre attention.",
  "No follow-up tasks are overdue or due in the next 7 days.":"Aucun suivi n'est en retard ni prévu dans les 7 prochains jours.",
  "Find the opportunity. Prove it. Turn it into action.":"Trouvez l'opportunité. Prouvez-la. Transformez-la en action.",
  "One monthly plan should take you from an early idea to evidence, a clear decision, and a governed Mission.":"Un seul forfait mensuel doit vous mener d'une idée naissante aux preuves, à une décision claire et à une Mission encadrée.",
  "Proposed launch pricing, not active offers. Paid billing and usage enforcement are not enabled; AI Opportunity Brief access is restricted to an approved preview tester.":"Tarifs de lancement proposés, non des offres actives. La facturation et les limites d'usage ne sont pas activées ; l'accès aux rapports d'opportunité IA est réservé à un testeur approuvé.",
  "Proposed monthly plans":"Forfaits mensuels proposés",
  "per month (proposed)":"par mois (proposé)",
  "Start free":"Commencer gratuitement",
  "The product we intend to build":"Le produit que nous comptons construire",
  "Opportunity Intelligence belongs inside the monthly plan—not as a surprise add-on.":"L'analyse des opportunités fait partie du forfait mensuel, pas d'un supplément surprise.",
  "The current early-access feature scores the information you enter, keeps your evidence ledger in this browser, and can turn a reviewed opportunity into a Mission. A guarded server-side AI analyst route exists for restricted preview access only. It is not generally available, and the route does not fetch source pages itself.":"La fonction d'accès anticipé actuelle évalue les informations saisies, conserve votre registre de preuves dans ce navigateur et peut transformer une opportunité examinée en Mission. Une route d'analyste IA côté serveur, protégée, existe uniquement pour un accès restreint en avant-première. Elle n'est pas disponible publiquement et ne récupère pas elle-même les pages sources.",
  "AI challenge: find weak assumptions, contradictions, missing evidence, and reasons an idea may fail.":"Défi IA : repérez les hypothèses fragiles, les contradictions, les preuves manquantes et les raisons d'échec possibles.",
  "Evidence-first report: each factual claim must cite a source or be clearly labeled as an inference or unknown.":"Rapport fondé sur les preuves : chaque affirmation factuelle doit citer une source ou être clairement signalée comme déduction ou inconnue.",
  "Market gap: compare relevant competitors, the prices they publish, customer pain signals, and unmet needs when reliable source data is available.":"Écart de marché : comparez les concurrents pertinents, les prix qu'ils publient, les signaux de frustration client et les besoins non satisfaits lorsque des données fiables existent.",
  "Next best test: recommend a low-cost experiment with success/failure criteria, then create a governed Mission for the user to review.":"Meilleur test suivant : recommandez une expérience peu coûteuse avec des critères de réussite et d'échec, puis créez une Mission encadrée à examiner.",
  "These are planned capabilities, not currently available features. The monthly report allowances and prices are hypotheses until provider costs, source access, report quality, and demand are tested.":"Ce sont des capacités prévues, pas des fonctionnalités disponibles. Les quotas mensuels de rapports et les prix restent des hypothèses tant que les coûts fournisseur, l'accès aux sources, la qualité des rapports et la demande n'ont pas été testés.",
  "Try the current Opportunity Intelligence MVP":"Essayez le MVP actuel d'Analyse des opportunités",
  "No unsupported promises.":"Aucune promesse sans fondement.",
  "The first version must be useful without AI; the paid analyst should launch only after source-backed reports, safe limits, privacy controls, and cost per report have been verified.":"La première version doit être utile sans IA ; l'analyste payant ne devrait être lancé qu'après vérification des rapports sourcés, des limites de sécurité, des contrôles de confidentialité et du coût par rapport.",
  "Back to ZAVQERA":"Retour à ZAVQERA",
