  "Your radar starts here":"Votre radar commence ici",
  "Add your first opportunity to begin comparing options. The score is a guide to support your decision, not a market forecast.":"Ajoutez votre première opportunité pour commencer à comparer. Le score est un repère pour appuyer votre décision, pas une prévision de marché.",
