  "Keep your opportunity data portable":"Gardez vos données d'opportunités portables",
  "Export your opportunities and evidence notes to a backup file, or merge a backup from another device. Data stays in this browser unless you move it yourself.":"Exportez vos opportunités et notes de preuves vers un fichier de sauvegarde, ou fusionnez une sauvegarde depuis un autre appareil. Les données restent dans ce navigateur sauf si vous les déplacez.",
  "Checking backup file…":"Vérification du fichier de sauvegarde…",
  "Import and merge":"Importer et fusionner",
  "Existing records with matching IDs will be skipped. Nothing currently saved will be overwritten.":"Les enregistrements existants aux ID identiques seront ignorés. Rien de ce qui est enregistré ne sera écrasé.",
  "Privacy and portability: opportunities and evidence notes are stored only in this browser. Export a backup to move them to another device; the file may contain sensitive business information, so store it securely. Import merges records and skips matching IDs without overwriting existing data. Cloud sync, live discovery, automatic source verification, recurring monitoring, and outcome-based learning are not connected yet.":"Confidentialité et portabilité : les opportunités et les notes de preuves ne sont stockées que dans ce navigateur. Exportez une sauvegarde pour les transférer vers un autre appareil ; le fichier peut contenir des informations d'entreprise sensibles, conservez-le en sécurité. L'import fusionne les enregistrements et ignore les ID identiques sans écraser les données existantes. La synchronisation cloud, la découverte en direct, la vérification automatique des sources, la veille récurrente et l'apprentissage fondé sur les résultats ne sont pas encore connectés.",
