  "This looks like a regulated activity. Nothing here tells you what the rules are — the first step is to get them in writing from the authority that sets them.":"Cela ressemble à une activité réglementée. Rien ici ne vous dit quelles sont les règles : la première étape est de les obtenir par écrit auprès de l'autorité qui les fixe.",
