  "Missions are private to you today. If you want to invite colleagues, tell us and we will let you know when invitations open.":"Missionen sind heute nur für Sie sichtbar. Wenn Sie Kolleginnen und Kollegen einladen möchten, sagen Sie es uns – wir melden uns, sobald Einladungen möglich sind.",
  "Working with a team?":"Arbeiten Sie im Team?",
