  "Create your first mission to start tracking a concrete outcome.":"Erstellen Sie Ihre erste Mission, um ein konkretes Ergebnis zu verfolgen.",
  "Create first mission":"Erste Mission erstellen",
  "Missions and follow-ups that need your attention.":"Missionen und Nachverfolgungen, die Ihre Aufmerksamkeit brauchen.",
  "No follow-up tasks are overdue or due in the next 7 days.":"Keine Nachverfolgung ist überfällig oder in den nächsten 7 Tagen fällig.",
  "Find the opportunity. Prove it. Turn it into action.":"Finden Sie die Chance. Belegen Sie sie. Machen Sie daraus Handeln.",
  "One monthly plan should take you from an early idea to evidence, a clear decision, and a governed Mission.":"Ein Monatsplan soll Sie von der frühen Idee zu Belegen, einer klaren Entscheidung und einer gesteuerten Mission führen.",
  "Proposed launch pricing, not active offers. Paid billing and usage enforcement are not enabled; AI Opportunity Brief access is restricted to an approved preview tester.":"Vorgeschlagene Startpreise, keine aktiven Angebote. Abrechnung und Nutzungsgrenzen sind nicht aktiviert; der Zugang zu KI-Chancenberichten ist auf einen freigegebenen Tester beschränkt.",
  "Proposed monthly plans":"Vorgeschlagene Monatspläne",
  "per month (proposed)":"pro Monat (vorgeschlagen)",
  "Start free":"Kostenlos starten",
  "The product we intend to build":"Das Produkt, das wir bauen wollen",
  "Opportunity Intelligence belongs inside the monthly plan—not as a surprise add-on.":"Chancenanalyse gehört in den Monatsplan – nicht als überraschender Zusatz.",
  "The current early-access feature scores the information you enter, keeps your evidence ledger in this browser, and can turn a reviewed opportunity into a Mission. A guarded server-side AI analyst route exists for restricted preview access only. It is not generally available, and the route does not fetch source pages itself.":"Die aktuelle Early-Access-Funktion bewertet die eingegebenen Informationen, hält Ihr Belegregister in diesem Browser und kann eine geprüfte Chance in eine Mission überführen. Eine abgesicherte serverseitige KI-Analystenroute besteht nur für eingeschränkten Vorabzugang. Sie ist nicht allgemein verfügbar und ruft Quellseiten nicht selbst ab.",
  "AI challenge: find weak assumptions, contradictions, missing evidence, and reasons an idea may fail.":"KI-Prüfung: schwache Annahmen, Widersprüche, fehlende Belege und mögliche Gründe für ein Scheitern finden.",
  "Evidence-first report: each factual claim must cite a source or be clearly labeled as an inference or unknown.":"Belegbasierter Bericht: Jede Tatsachenbehauptung muss eine Quelle nennen oder klar als Schlussfolgerung bzw. unbekannt gekennzeichnet sein.",
  "Market gap: compare relevant competitors, the prices they publish, customer pain signals, and unmet needs when reliable source data is available.":"Marktlücke: relevante Wettbewerber, deren veröffentlichte Preise, Signale für Kundenprobleme und unerfüllte Bedürfnisse vergleichen, sofern verlässliche Quelldaten vorliegen.",
  "Next best test: recommend a low-cost experiment with success/failure criteria, then create a governed Mission for the user to review.":"Nächster bester Test: ein kostengünstiges Experiment mit Erfolgs- und Misserfolgskriterien empfehlen und daraus eine geprüfte Mission erstellen.",
  "These are planned capabilities, not currently available features. The monthly report allowances and prices are hypotheses until provider costs, source access, report quality, and demand are tested.":"Dies sind geplante Fähigkeiten, keine derzeit verfügbaren Funktionen. Monatliche Berichtskontingente und Preise sind Hypothesen, bis Anbieterkosten, Quellenzugang, Berichtsqualität und Nachfrage geprüft sind.",
  "Try the current Opportunity Intelligence MVP":"Das aktuelle MVP der Chancenanalyse testen",
  "No unsupported promises.":"Keine unbelegten Versprechen.",
  "The first version must be useful without AI; the paid analyst should launch only after source-backed reports, safe limits, privacy controls, and cost per report have been verified.":"Die erste Version muss ohne KI nützlich sein; der bezahlte Analyst sollte erst starten, wenn quellenbelegte Berichte, sichere Grenzen, Datenschutzkontrollen und Kosten pro Bericht geprüft sind.",
