  "How the score works":"So entsteht der Score",
  "Priority =":"Priorität =",
  "Rate each factor from 1 to 5. Be conservative where evidence is weak.":"Bewerten Sie jeden Faktor von 1 bis 5. Seien Sie zurückhaltend, wo Belege schwach sind.",
