  "Scores explain your inputs; they are not market forecasts or a promise of revenue.":"Die Scores erklären Ihre Eingaben; sie sind keine Marktprognosen und kein Umsatzversprechen.",
  "Step 1 · Capture":"Schritt 1 · Erfassen",
