  "Add an opportunity":"Chance hinzufügen",
  "Write down the opportunity and the assumptions behind it. Start with a hypothesis; evidence can be added later.":"Notieren Sie die Chance und die Annahmen dahinter. Beginnen Sie mit einer Hypothese; Belege können später folgen.",
