  "Your radar starts here":"Ihr Radar beginnt hier",
  "Add your first opportunity to begin comparing options. The score is a guide to support your decision, not a market forecast.":"Fügen Sie Ihre erste Chance hinzu, um Optionen zu vergleichen. Der Score ist eine Orientierung für Ihre Entscheidung, keine Marktprognose.",
