  "Keep your opportunity data portable":"Halten Sie Ihre Chancendaten portabel",
  "Export your opportunities and evidence notes to a backup file, or merge a backup from another device. Data stays in this browser unless you move it yourself.":"Exportieren Sie Chancen und Belegnotizen in eine Sicherungsdatei oder führen Sie eine Sicherung von einem anderen Gerät zusammen. Die Daten bleiben in diesem Browser, sofern Sie sie nicht selbst verschieben.",
  "Checking backup file…":"Sicherungsdatei wird geprüft …",
  "Import and merge":"Importieren und zusammenführen",
  "Existing records with matching IDs will be skipped. Nothing currently saved will be overwritten.":"Vorhandene Einträge mit gleicher ID werden übersprungen. Nichts bereits Gespeichertes wird überschrieben.",
  "Privacy and portability: opportunities and evidence notes are stored only in this browser. Export a backup to move them to another device; the file may contain sensitive business information, so store it securely. Import merges records and skips matching IDs without overwriting existing data. Cloud sync, live discovery, automatic source verification, recurring monitoring, and outcome-based learning are not connected yet.":"Datenschutz und Portabilität: Chancen und Belegnotizen werden nur in diesem Browser gespeichert. Exportieren Sie eine Sicherung, um sie auf ein anderes Gerät zu übertragen; die Datei kann sensible Geschäftsdaten enthalten, bewahren Sie sie sicher auf. Der Import führt Einträge zusammen und überspringt gleiche IDs, ohne vorhandene Daten zu überschreiben. Cloud-Synchronisierung, Live-Erkennung, automatische Quellenprüfung, laufende Beobachtung und ergebnisbasiertes Lernen sind noch nicht angebunden.",
