  "Record the specific observation, not a conclusion the source does not support. Avoid confidential or sensitive personal information.":"Erfassen Sie die konkrete Beobachtung, nicht eine Schlussfolgerung, die die Quelle nicht trägt. Vermeiden Sie vertrauliche oder sensible personenbezogene Daten.",
