  "Let AI draft the shape of this work":"Lassen Sie die KI die Form dieser Arbeit entwerfen",
  "It will suggest the steps and what each one is for. It will not tell you a fee, a waiting time or a rule: it has looked nothing up, so anything external comes back as where to confirm it.":"Sie schlägt die Schritte vor und wozu jeder dient. Sie nennt keine Gebühr, keine Wartezeit und keine Regel: Sie hat nichts nachgeschlagen, daher kommt alles Externe als Hinweis zurück, wo es zu bestätigen ist.",
