export const DICTIONARIES: Record<AppLanguage, Record<string, string>> = {
  en: {}, nb: NB, ar: AR, es: ES, fr: FR, de: DE,
};

/** Resolve one English source string for a language, falling back to English. */
/**
 * A key may carry a context after a vertical bar — "Active|one mission" — so
 * that one English word can take two translations where a language needs
 * them. Norwegian says "Aktiv" of a single mission and "Aktive" of a count of
 * them; a dictionary keyed by the English alone cannot hold both, and picking
 * either one is wrong somewhere.
 *
 * The context never reaches a reader: English falls back to the part before
 * the bar, and a missing key does the same rather than printing the marker.
 */
export function translate(en: string, language: AppLanguage): string {
  const translated = DICTIONARIES[language][en];
  if (translated !== undefined) return translated;
  const bar = en.indexOf("|");
  return bar === -1 ? en : en.slice(0, bar);
}
